// Some portions generated by Co-Pilot
import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import LogosGrid from "../index";
import members from "@/data/members.json";

describe("Compact member logo grid", () => {
  it("balances padded logo assets without modifying or stretching artwork", () => {
    render(
      <LogosGrid
        type="infra"
        compact
        logos={members.filter((member) => member.tier === "infra")}
      />,
    );
    expect(
      screen.getByRole("img", { name: "Microsoft Azure" }).parentElement,
    ).toHaveStyle({ height: "80px" });
    expect(
      screen.getByRole("img", { name: "Heroku" }).parentElement,
    ).toHaveStyle({ height: "80px" });
    expect(
      screen.getByRole("img", { name: "JFrog" }).parentElement,
    ).toHaveStyle({ height: "64px" });
    expect(
      screen.getByRole("img", { name: "Macincloud" }).parentElement,
    ).toHaveStyle({ maxWidth: "176px" });
    for (const image of screen.getAllByRole("img"))
      expect(image).toHaveClass("object-contain");
  });

  it("preserves each organisation's destination and accessible name", () => {
    const logos = members.filter((member) => member.tier === "sponsor");
    render(<LogosGrid type="sponsor" compact logos={logos} />);
    for (const logo of logos) {
      const link = screen.getByRole("link", { name: logo.name });
      expect(link).toHaveAttribute("href", logo.url);
      expect(link).toHaveAttribute("rel", "noopener noreferrer");
    }
  });
});
